package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TypeFactory.rawClass
 */
public class TypeFactory_rawClass_TriageGen1Test {

    @Test
    public void testRawClass_WithClassType() {
        // Test branch: if (t instanceof Class<?>)
        Class<String> stringClass = String.class;
        Class<?> result = TypeFactory.rawClass(stringClass);
        assertEquals(stringClass, result);
    }

    @Test
    public void testRawClass_WithParameterizedType() {
        // Test branch: return defaultInstance().constructType(t).getRawClass();
        // Using a ParameterizedType (e.g., List<String>)
        Type parameterizedType = new ParameterizedTypeImpl(List.class, new Type[0], new Type[]{String.class});

        Class<?> result = TypeFactory.rawClass(parameterizedType);
        assertEquals(List.class, result);
    }

    @Test
    public void testRawClass_WithArrayType() {
        // Test branch: return defaultInstance().constructType(t).getRawClass();
        // Using an Array type
        Type arrayType = String[].class;
        // Note: String[].class is an instance of Class, so it hits the first branch.
        // To force the second branch with an array, we use a generic array type if possible, 
        // but in Java, Class<?> covers most array cases. 
        // However, we can test via a constructed JavaType if needed.

        Class<?> result = TypeFactory.rawClass(arrayType);
        assertEquals(arrayType, result);
    }

    @Test
    public void testRawClass_WithComplexType() {
        // Test branch: return defaultInstance().constructType(t).getRawClass();
        // Testing a nested type: Map<String, List<Integer>>
        TypeFactory tf = TypeFactory.defaultInstance();
        Type type = tf.constructType(java.util.Map.class)
                .withSubTypes(tf.constructType(String.class), tf.constructType(java.util.List.class))
                .getRawClass(); // This is just a placeholder logic

        // Real test: construct a type that isn't a Class instance directly
        // We use a TypeReference style construction via constructType
        Type complexType = tf.constructType(new com.fasterxml.jackson.core.type.TypeReference<java.util.Map<String, java.util.List<Integer>>>() {});

        Class<?> result = TypeFactory.rawClass(complexType);
        assertEquals(java.util.Map.class, result);
    }

    /**
     * Helper class to simulate ParameterizedType for testing the non-Class branch
     */
    private static class ParameterizedTypeImpl implements ParameterizedType {
        private final Class<?> rawType;
        private final Type[] typeArguments;
        private final Type[] actualTypeArguments;

        public ParameterizedTypeImpl(Class<?> rawType, Type[] typeArguments, Type[] actualTypeArguments) {
            this.rawType = rawType;
            this.typeArguments = typeArguments;
            this.actualTypeArguments = actualTypeArguments;
        }

        @Override
        public Type[] getActualTypeArguments() {
            return actualTypeArguments;
        }

        @Override
        public Type[] getGenericSuperType() {
            return null;
        }

        @Override
        public Class<?> getRawType() {
            return rawType;
        }
    }
}
